import{_ as e,o as r,c as o,ag as l}from"./chunks/framework.QfQ7DfGu.js";const f=JSON.parse('{"title":"其他扩展阅读","description":"","frontmatter":{"title":"其他扩展阅读","outline":"deep"},"headers":[],"relativePath":"misc/news.md","filePath":"misc/news.md"}'),t={name:"misc/news.md"};function n(i,a,h,p,s,c){return r(),o("div",null,[...a[0]||(a[0]=[l('<h1 id="其他扩展阅读" tabindex="-1">其他扩展阅读 <a class="header-anchor" href="#其他扩展阅读" aria-label="Permalink to &quot;其他扩展阅读&quot;">​</a></h1><h2 id="_1-咱龙了吗" tabindex="-1">1. 咱龙了吗 <a class="header-anchor" href="#_1-咱龙了吗" aria-label="Permalink to &quot;1. 咱龙了吗&quot;">​</a></h2><p>这里是社区建立的一个关于龙架构的咨询网站，你可以了解一些软件的最新消息，</p><p>LoongArch生态的情况。</p><p>网站<a href="https://areweloongyet.com/docs/intro" target="_blank" rel="noreferrer">在这里</a></p><h2 id="_2-龙芯爱好者社区" tabindex="-1">2. 龙芯爱好者社区 <a class="header-anchor" href="#_2-龙芯爱好者社区" aria-label="Permalink to &quot;2. 龙芯爱好者社区&quot;">​</a></h2><p>本论坛为想要在龙架构生态中进行软硬件开发的工程师们提供帮助与支持</p><p>网站<a href="https://www.loongbbs.cn/" target="_blank" rel="noreferrer">在这里</a></p><h2 id="_3-龙架构双周会" tabindex="-1">3. 龙架构双周会 <a class="header-anchor" href="#_3-龙架构双周会" aria-label="Permalink to &quot;3. 龙架构双周会&quot;">​</a></h2><p>龙架构双周会是由龙芯爱好者组织的社区会议，会议议程包括针对上游及各 Linux 发行版及其他系统项目的开发进展报告、社区事务报告，以及贡献者讨论及问答环节。</p><p>龙架构双周会一般于 UTC+8 时区的每两周周日 14:00 在腾讯会议举办，原则上避开中国大陆预期出行较多的法定假期（如春节、国庆等）与调休工作日。</p><p>会议进程于 Bilibili @龙芯爱好者社区 账号同步直播，亦时有安排线下活动。</p><p>网站<a href="https://loongfans.cn/biweekly" target="_blank" rel="noreferrer">在这里</a></p><h2 id="_4-龙架构的哔哩哔哩" tabindex="-1">4. 龙架构的哔哩哔哩 <a class="header-anchor" href="#_4-龙架构的哔哩哔哩" aria-label="Permalink to &quot;4. 龙架构的哔哩哔哩&quot;">​</a></h2><p>可以看到很多有趣好玩的东西！</p><p>链接<a href="https://space.bilibili.com/70360929" target="_blank" rel="noreferrer">在这里</a></p><h2 id="_5-龙架构漂流板-loongfly" tabindex="-1">5. 龙架构漂流板(LoongFly) <a class="header-anchor" href="#_5-龙架构漂流板-loongfly" aria-label="Permalink to &quot;5. 龙架构漂流板(LoongFly)&quot;">​</a></h2><p>龙芯1024计划旨在为开发者提供全面支持，通过项目和服务提升开发效率和应用性能，促进龙芯生态系统发展。旨在创建一个高效、友好的龙架构开发环境。</p><p>计划包括:</p><ul><li>开发环境支持</li><li>文档资源下载</li><li>社区论坛讨论</li></ul><p>开发者可获得最新技术信息、资源和专业支持，创造优秀作品。 计划还鼓励社区贡献新工具，不断优化开发环境。文档体系全面，覆盖各层次，提供示例代码和案例分析，定期更新以保持信息时效性。</p><p>龙架构漂流板(1024计划)活动由龙芯爱好者社区(<a href="mailto:support@loongfans.com" target="_blank" rel="noreferrer">support@loongfans.com</a>)运营, 计划初期项目缺少自动化流程包含大量人工操作, 如有纰漏欢迎指正。</p><p>网站<a href="https://github.com/loongson-community/1024" target="_blank" rel="noreferrer">在这里</a></p><h2 id="_6-龙架构悬赏与实习机会" tabindex="-1">6. 龙架构悬赏与实习机会 <a class="header-anchor" href="#_6-龙架构悬赏与实习机会" aria-label="Permalink to &quot;6. 龙架构悬赏与实习机会&quot;">​</a></h2><p>社区悬赏项目</p><p>网站<a href="https://loongfans.cn/jobs" target="_blank" rel="noreferrer">在这里</a></p><h2 id="_7-千问客户端v2-3-2-for-linux" tabindex="-1">7. 千问客户端v2.3.2 for linux <a class="header-anchor" href="#_7-千问客户端v2-3-2-for-linux" aria-label="Permalink to &quot;7. 千问客户端v2.3.2 for linux&quot;">​</a></h2><p>Linux版千问客户端，支持登录，支持上传/下载文件 注：需要登录才能使用完整功能</p><p>网站<a href="https://github.com/kota-rina3/hokeshi/releases/download/qwen-linux-2.3.2/com.qianwen.otohime_2.3.2-fix1_loong64.deb" target="_blank" rel="noreferrer">在这里</a></p><h2 id="_8-liblol" tabindex="-1">8. libLoL <a class="header-anchor" href="#_8-liblol" aria-label="Permalink to &quot;8. libLoL&quot;">​</a></h2><p>libLoL (LoongArch on LoongArch) 是一款用于提供旧世界 ABI 兼容性的运行时。 旧世界 ABI 常用于为龙芯提供的 Loongnix 参考发行版和统信 UOS 设计的商业软件， 如腾讯 QQ Linux 版、金山 WPS for Linux 和龙芯浏览器等。由于这些应用程序尚未移植到新世界 ABI 上，本运行时旨在为新世界发行版用户提供运行上述应用程序的便利。</p><p>网站<a href="https://liblol.aosc.io/" target="_blank" rel="noreferrer">在这里</a></p>',32)])])}const b=e(t,[["render",n]]);export{f as __pageData,b as default};
